avg_stress = df['stress_level'].mean()

# Segments
steps_by_gender = df.groupby('gender')['steps'].mean().to_dict()
steps_by_workout = df.groupby('workout_type')['steps'].mean().to_dict()
steps_by_mood = df.groupby('mood')['steps'].mean().to_dict()
