# Monthly
monthly = df.groupby('month').agg(steps=('steps','mean'), calories=('calories_burned','mean'), sleep=('sleep_hours','mean'), stress=('stress_level','mean'))
# DOW
dow = df.groupby('dayofweek_name').agg(steps=('steps','mean'), stress=('stress_level','mean'))
order = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']
